local _, addon = ...
addon.localeData.enUS.texts = {
    FIREBALL = { name = "Fireball", ziel = { "Feel the heat, %s.", "*casts Fireball on %s.*", "%s, your armor is no substitute for fire resistance." }, gruppe = { "Feel the heat.", "*conjures Fireball.*", "The flame obeys my hand, not my temper.", "*closes a fist around a red-hot core of flame and hurls it forward.*", "A fireball is a promise made of flame, impossible to take back.", "*draws glowing threads taut until they begin to move of their own accord.*" } },
    FROSTBOLT = { name = "Frostbolt", ziel = { "A chilly greeting, %s.", "*casts Frostbolt on %s.*", "%s, each step will grow heavier now." }, gruppe = { "A chilly greeting.", "*conjures Frostbolt.*", "Winter needs no invitation.", "*draws a jagged shard of ice from the damp air.*", "One shard of frost is enough to slow reckless courage.", "*breathes out, tracing silver crystal lines through the air.*" } },
    ARCANE_MISSILES = { name = "Arcane Missiles", ziel = { "Arcane energies seek you, %s.", "*casts Arcane Missiles on %s.*", "%s, five thoughts, a single target." }, gruppe = { "Arcane energies seek you.", "*conjures Arcane Missiles.*", "The missiles will find their path through chaos.", "*splits a violet thread of light into seeking sparks.*", "Each missile follows a different rune, yet all converge on one point.", "*nudges a floating glyph by a hair's breadth and listens to its hum.*" } },
    FIRE_BLAST = { name = "Fire Blast", ziel = { "One spark will do, %s!", "*casts Fire Blast on %s.*", "%s, this requires no lengthy lecture." }, gruppe = { "One spark will do!", "*conjures Fire Blast.*", "One instant is enough when the spark is placed well.", "*snaps a finger and ignites the air with a sharp crack.*", "One snap, one blast, and a bad day for eyebrows.", "*draws glowing threads taut until they begin to move of their own accord.*" } },
    PYROBLAST = { name = "Pyroblast", ziel = { "Time for a proper firestorm, %s!", "*casts Pyroblast on %s.*", "%s, this incantation deserves some distance." }, gruppe = { "Time for a proper firestorm!", "*conjures Pyroblast.*", "Great flames demand a steady hand.", "*traces a broad circle of fire and compresses it into a roaring sphere.*", "This flame takes time to grow and leaves nowhere to hide.", "*draws glowing threads taut until they begin to move of their own accord.*" } },
    FLAMESTRIKE = { name = "Flamestrike", ziel = { "The ground itself shall burn!", "*casts Flamestrike on %s.*", "%s, mind where you stand." }, gruppe = { "The ground itself shall burn!", "*conjures Flamestrike.*", "The ground remembers every misplaced sigil.", "*draws a burning pattern beneath the enemies' feet.*", "The ground takes a sigil, then fire rains upon it.", "*draws glowing threads taut until they begin to move of their own accord.*" } },
    SCORCH = { name = "Scorch", ziel = { "Just a taste of fire, %s.", "*casts Scorch on %s.*", "%s, a brief lesson in applied heat." }, gruppe = { "Just a taste of fire.", "*conjures Scorch.*", "Not every flame needs to become an inferno.", "*brushes two fingers through the air, leaving a narrow trail of embers.*", "A swift spark often serves better than a towering blaze.", "*draws glowing threads taut until they begin to move of their own accord.*" } },
    BLIZZARD = { name = "Blizzard", ziel = { "Winter shows no mercy!", "*casts Blizzard on %s.*", "%s, you had better find warm shelter." }, gruppe = { "Winter shows no mercy!", "*conjures Blizzard.*", "When the sky falls silent, the snow speaks.", "*raises both arms and summons a swirl of snow and cutting ice.*", "The sky turns white long before the first foe begins to shiver.", "*breathes out, tracing silver crystal lines through the air.*" } },
    FROST_NOVA = { name = "Frost Nova", ziel = { "Not another step, %s!", "*casts Frost Nova on %s.*", "%s, your charge ends here." }, gruppe = { "Not another step!", "*conjures Frost Nova.*", "Cold draws a boundary no one can overlook.", "*presses a palm toward the ground and sends frost racing outward.*", "A circle of rime makes it very clear where you will stand.", "*breathes out, tracing silver crystal lines through the air.*" } },
    CONE_OF_COLD = { name = "Cone of Cold", ziel = { "A breath of the north!", "*casts Cone of Cold on %s.*", "%s, winter air is coming your way." }, gruppe = { "A breath of the north!", "*conjures Cone of Cold.*", "One breath is enough to make close quarters unpleasant.", "*spreads the fingers and drives a wedge of freezing air forward.*", "One cold breath, wide enough for a row of the unwary.", "*breathes out, tracing silver crystal lines through the air.*" } },
    ICE_BARRIER = { name = "Ice Barrier", ziel = {  }, gruppe = { "Cold is my shield.", "*conjures Ice Barrier.*", "My shield is woven from patience and frost.", "*layers delicate crystals of ice around the body.*", "Every layer of ice buys me another second.", "*closes a glittering circle of protection with a whispered syllable.*" } },
    ICE_BLOCK = { name = "Ice Block", ziel = {  }, gruppe = { "I am briefly unavailable.", "*conjures Ice Block.*", "Some attacks deserve no reply, only a pause.", "*closes the eyes as clear ice seals around the body.*", "Sometimes the best answer is one perfectly motionless moment.", "*closes a glittering circle of protection with a whispered syllable.*" } },
    ARCANE_EXPLOSION = { name = "Arcane Explosion", ziel = { "Stand back, the magic is restless!", "*casts Arcane Explosion on %s.*", "%s, step out of my spell circle." }, gruppe = { "Stand back, the magic is restless!", "*conjures Arcane Explosion.*", "Distance is sometimes the wisest arcane discipline.", "*throws both arms apart, unleashing a ring of violet energy.*", "The energy is everywhere before anyone notices the circle.", "*nudges a floating glyph by a hair's breadth and listens to its hum.*" } },
    COUNTERSPELL = { name = "Counterspell", ziel = { "Your incantation ends here, %s!", "*casts Counterspell on %s.*", "%s, your syllables are out of place." }, gruppe = { "Your incantation ends here!", "*conjures Counterspell.*", "A spell can shatter when a single syllable is stolen.", "*slices an opposing incantation in two with a pair of fingers.*", "One syllable too many, and your spell dissolves into silence.", "*nudges a floating glyph by a hair's breadth and listens to its hum.*" } },
    POLYMORPH = { name = "Polymorph", ziel = { "A little wool suits you, %s.", "*casts Polymorph on %s.*", "%s, you seemed considerably taller a moment ago." }, gruppe = { "A little wool suits you.", "*conjures Polymorph.*", "A woollier appearance might suit you.", "*sketches the outline of a sheep.*", "A little humility, four hooves and a great deal of wool.", "*shapes the outline of a sheep from light and folds it over the target.*", "Transformation is a precise art; the fleece is incidental.", "*checks the spell's outline for any unexpected horns.*", "A temporary change of shape can be wonderfully persuasive.", "A different shape can offer a startling change of perspective.", "*turns a rune and watches the outlines shift.*" } },
    BLINK = { name = "Blink", ziel = {  }, gruppe = { "Just a moment, I will be elsewhere.", "*conjures Blink.*", "The shortest path is not always the visible one.", "*vanishes into a thin blue seam of light and reappears a heartbeat later.*", "The space between two steps is merely a matter of practice.", "*rotates the coordinates of a floating map toward the light.*" } },
    SLOW_FALL = { name = "Slow Fall", ziel = { "Gravity can wait today.", "*casts Slow Fall on %s.*", "Gravity shall make an exception today.", "*traces a weightless arc beneath %s's boots.*" }, gruppe = { "Gravity can wait today.", "*conjures Slow Fall.*", "Gravity shall make an exception today.", "*traces a weightless arc beneath the boots.*", "Gravity can wait its turn for a moment.", "*rotates the coordinates of a floating map toward the light.*" } },
    EVOCATION = { name = "Evocation", ziel = {  }, gruppe = { "A moment to gather my thoughts and mana.", "*conjures Evocation.*", "Even great art occasionally needs a moment to breathe.", "*slowly draws scattered mana sparks back into both palms.*", "Mana returns when I stop scattering the currents.", "*nudges a floating glyph by a hair's breadth and listens to its hum.*" } },
    ARCANE_INTELLECT = { name = "Arcane Intellect", ziel = { "A sharp mind is your finest weapon, %s.", "*casts Arcane Intellect on %s.*", "%s, may your mind be keener than your blade." }, gruppe = { "A sharp mind is your finest weapon.", "*conjures Arcane Intellect.*", "An alert mind is the most reliable talisman.", "*places a small luminous glyph beside the temple.*", "A sharper thought is worth more than a sharper blade.", "*sets a gleaming thread of magic over an outstretched palm.*" } },
    ARCANE_BRILLIANCE = { name = "Arcane Brilliance", ziel = { "May our minds shine brighter!", "*casts Arcane Brilliance on %s.*", "%s, knowledge improves when shared." }, gruppe = { "May our minds shine brighter!", "*conjures Arcane Brilliance.*", "The wisest company thinks together.", "*spreads a web of bright runes over the allies.*", "A circle of keen minds outshines solitary genius.", "*sets a gleaming thread of magic over an outstretched palm.*" } },
    MANA_SHIELD = { name = "Mana Shield", ziel = {  }, gruppe = { "Mana into shelter, thought into steel.", "*conjures Mana Shield.*", "My thoughts are harder to pierce than my robes.", "*wraps flowing threads of mana around the shoulders.*", "I'd rather spend mana than sacrifice my last robe.", "*closes a glittering circle of protection with a whispered syllable.*" } },
    CONJURE_FOOD = { name = "Conjure Food", ziel = {  }, gruppe = { "A little magic against hunger.", "*conjures Conjure Food.*", "Good magic occasionally satisfies hunger as well.", "*opens both hands and produces a pleasantly fragrant snack.*", "The highest art of magic ought to impress the stomach, too.", "*gathers scattered sparks into something solid enough to touch.*" } },
    CONJURE_WATER = { name = "Conjure Water", ziel = {  }, gruppe = { "Fresh water, drawn from pure magic.", "*conjures Conjure Water.*", "Drink. Arcane studies are thirsty work.", "*catches a drop of light and turns it into clear water.*", "One drop from nowhere, and the journey becomes bearable.", "*gathers scattered sparks into something solid enough to touch.*" } },
    CREATE_MANA_GEM = { name = "Conjure Mana Gem", ziel = {  }, gruppe = { "A little reserve for dire moments.", "*conjures Conjure Mana Gem.*", "A small reserve for a large problem.", "*presses flickering mana into a cool, glowing gem.*", "A small crystal, carefully packed with reserve power.", "*gathers scattered sparks into something solid enough to touch.*" } },
    PORTAL = { name = "Portal", ziel = {  }, gruppe = { "Mind your limbs when stepping through.", "*conjures Portal.*", "Anyone stepping through should trust the destination circle.", "*carefully opens a round fold in the fabric of space.*", "A doorway is useful only when its far end is where you expect.", "*rotates the coordinates of a floating map toward the light.*" } },
    TELEPORT = { name = "Teleport", ziel = {  }, gruppe = { "I shall take the shortcut through space.", "*conjures Teleport.*", "One step, one wrong coordinate, a thousand miles astray.", "*traces the destination rune and dissolves into a whirl of light.*", "I fold distance instead of travelling through it.", "*rotates the coordinates of a floating map toward the light.*" } },
    REMOVE_LESSER_CURSE = { name = "Remove Lesser Curse", ziel = { "This curse has no place here, %s.", "*casts Remove Lesser Curse on %s.*", "%s, this curse has clung on long enough." }, gruppe = { "This curse has no place here.", "*conjures Remove Lesser Curse.*", "No binding lasts forever when you know its knots.", "*uses a shining rune to lift a shadow from a shoulder.*", "Every curse has a knot, and I know where to loosen it.", "*sets a gleaming thread of magic over an outstretched palm.*" } },
    DETECT_MAGIC = { name = "Detect Magic", ziel = { "Let us see what secrets you carry, %s.", "*casts Detect Magic on %s.*", "%s, your aura reveals more than your words." }, gruppe = { "Let us see what secrets you carry.", "*conjures Detect Magic.*", "Hidden currents always leave a trace.", "*holds a shimmering sigil to the light and studies its response.*", "Invisible threads often reveal more than shining armour.", "*nudges a floating glyph by a hair's breadth and listens to its hum.*" } },
    DAMPEN_MAGIC = { name = "Dampen Magic", ziel = { "%s, a little less magical noise will do you good.", "Not every power needs to speak at full volume.", "*lays a silvery veil over the pulsing mana currents.*", "%s, let us quiet the sorcery swirling around you." }, gruppe = { "Not every power needs to speak at full volume.", "*lays a silvery veil over the pulsing mana currents.*", "I soften the current before it becomes a torrent.", "*sets a gleaming thread of magic over an outstretched palm.*" } },
    AMPLIFY_MAGIC = { name = "Amplify Magic", ziel = { "%s, I open your senses to stronger currents.", "More power is a gift only if you can guide it.", "*widens the glowing circle around an ally with a measured gesture.*", "%s, prepare for a stronger surge of magic." }, gruppe = { "More power is a gift only if you can guide it.", "*widens the glowing circle around an ally with a measured gesture.*", "A touch more resonance, provided the hand stays steady.", "*sets a gleaming thread of magic over an outstretched palm.*" } },
    FROST_ARMOR = { name = "Frost Armor", ziel = {  }, gruppe = { "A cool head deserves armor to match.", "*draws a shimmering frost rim around shoulders and arms.*", "A cloak of cold leaves no seam unguarded.", "*closes a glittering circle of protection with a whispered syllable.*" } },
    ICE_ARMOR = { name = "Ice Armor", ziel = {  }, gruppe = { "Anyone who touches me shall greet winter first.", "*grows hard plates of ice across the robe like scales.*", "The ice rests close, light as cloth and hard as stone.", "*closes a glittering circle of protection with a whispered syllable.*" } },
    MAGE_ARMOR = { name = "Mage Armor", ziel = {  }, gruppe = { "Arcane discipline begins just beneath my robes.", "*kindles a barely visible layer of protective glyphs.*", "Arcane patterns protect best when every line interlocks.", "*closes a glittering circle of protection with a whispered syllable.*" } },
    FIRE_WARD = { name = "Fire Ward", ziel = {  }, gruppe = { "Fire recognizes fire, but not every flame may pass.", "*closes a golden ring of fire into a warding seal.*", "Fire is welcome so long as it stays on the other side.", "*closes a glittering circle of protection with a whispered syllable.*" } },
    FROST_WARD = { name = "Frost Ward", ziel = {  }, gruppe = { "Winter knocks. My answer is already prepared.", "*raises a transparent circle of crystal against the freezing air.*", "That cold stays outside; I've already summoned enough of my own.", "*closes a glittering circle of protection with a whispered syllable.*" } },
    ARCANE_BLAST = { name = "Arcane Blast", ziel = { "%s, there is no arguing away this energy.", "Raw power needs no flame to leave its mark.", "*drives a dense surge of violet light forward.*", "%s, the air itself is about to strike you." }, gruppe = { "Raw power needs no flame to leave its mark.", "*drives a dense surge of violet light forward.*", "One sharp pulse sets the entire pattern trembling.", "*nudges a floating glyph by a hair's breadth and listens to its hum.*" } },
    ARCANE_WRATH = { name = "Arcane Wrath", ziel = { "%s, my patience was your final layer of protection.", "The arcane answers foolishness with emphasis.", "*twists two floating sigils until a bright pulse bursts from between them.*", "%s, you have tested the patience of the arcane." }, gruppe = { "The arcane answers foolishness with emphasis.", "*twists two floating sigils until a bright pulse bursts from between them.*", "When the runes turn wrathful, even mana pays attention.", "*nudges a floating glyph by a hair's breadth and listens to its hum.*" } },
    ARCANE_POWER = { name = "Arcane Power", ziel = {  }, gruppe = { "Now theory may show what it is truly worth.", "*opens both hands as bright rings of runes spin faster together.*", "For one moment, I open the floodgates wider than usual.", "*nudges a floating glyph by a hair's breadth and listens to its hum.*" } },
    PRESENCE_OF_MIND = { name = "Presence of Mind", ziel = {  }, gruppe = { "Some thoughts move faster than the tongue.", "*pauses as if every possible path has suddenly become visible.*", "The thought arrives before my hands begin to move.", "*nudges a floating glyph by a hair's breadth and listens to its hum.*" } },
    BLAST_WAVE = { name = "Blast Wave", ziel = { "%s, you are standing too close to my center.", "When the air strikes back, distance is a sensible choice.", "*claps both palms together, sending a scorching shock wave outward.*", "%s, I suggest you brace against the coming heat." }, gruppe = { "When the air strikes back, distance is a sensible choice.", "*claps both palms together, sending a scorching shock wave outward.*", "The air itself becomes a fist of heat.", "*draws glowing threads taut until they begin to move of their own accord.*" } },
    COMBUSTION = { name = "Combustion", ziel = {  }, gruppe = { "Every ember shall give its last spark today.", "*draws the heat of the surroundings into a single flickering flame.*", "I tend the ember until it outshines everything else.", "*draws glowing threads taut until they begin to move of their own accord.*" } },
    FROSTFIRE_BOLT = { name = "Frostfire Bolt", ziel = { "%s, choose quickly between frost and flame.", "A contradiction? Only to a poor mage.", "*weaves blue shards of ice through red strands of flame into a single bolt.*", "%s, you will feel the winter and the furnace together." }, gruppe = { "A contradiction? Only to a poor mage.", "*weaves blue shards of ice through red strands of flame into a single bolt.*", "Frost and flame disagree only at first glance.", "*draws glowing threads taut until they begin to move of their own accord.*" } },
    FELFIRE = { name = "Felfire", ziel = { "%s, even this alien flame answers to a well-drawn seal.", "Green fire demands greater care, not less thought.", "*contains a restless green flame within a narrow ring of runes.*", "%s, even a strange flame can be given direction." }, gruppe = { "Green fire demands greater care, not less thought.", "*contains a restless green flame within a narrow ring of runes.*", "This green flame demands an exceptionally steady hand.", "*draws glowing threads taut until they begin to move of their own accord.*" } },
    ICE_LANCE = { name = "Ice Lance", ziel = { "%s, a single shard is answer enough.", "Ice need not be large to be sharp.", "*presses glittering frost into a needle-thin lance.*", "%s, the smallest icicle can find the weakest seam." }, gruppe = { "Ice need not be large to be sharp.", "*presses glittering frost into a needle-thin lance.*", "An ice lance need not be large, only relentlessly straight.", "*breathes out, tracing silver crystal lines through the air.*" } },
    FROST_BLAST = { name = "Frost Blast", ziel = { "%s, this winter comes without warning.", "Cold in a single, relentless heartbeat.", "*unleashes a violent burst of frost from an open fist.*", "%s, you will not hear the frost before it strikes." }, gruppe = { "Cold in a single, relentless heartbeat.", "*unleashes a violent burst of frost from an open fist.*", "The cold does not strike; it steals the warmth from the moment.", "*breathes out, tracing silver crystal lines through the air.*" } },
    COLD_SNAP = { name = "Cold Snap", ziel = {  }, gruppe = { "Time is just another variable in the art of frost.", "*breaks a floating snowflake and rearranges the frost sigils.*", "One breath, and winter begins anew.", "*breathes out, tracing silver crystal lines through the air.*" } },
    CONJURE_MANA_AGATE = { name = "Conjure Mana Agate", ziel = {  }, gruppe = { "An agate small enough for a pocket and strong enough for a rescue.", "*pours a narrow stream of mana into a forming agate.*", "This agate keeps a small piece of tomorrow for today.", "*gathers scattered sparks into something solid enough to touch.*" } },
    CONJURE_MANA_JADE = { name = "Conjure Mana Jade", ziel = {  }, gruppe = { "Jade stores magic almost as patiently as a scholar.", "*settles green light into a smoothly polished mana gem.*", "Jade keeps mana calm even when my thoughts race.", "*gathers scattered sparks into something solid enough to touch.*" } },
    CONJURE_MANA_CITRINE = { name = "Conjure Mana Citrine", ziel = {  }, gruppe = { "A little golden sunlight for the hours when strength runs low.", "*forms a warmly glowing citrine from golden sparks.*", "The citrine catches a golden trace of arcane light.", "*gathers scattered sparks into something solid enough to touch.*" } },
    CONJURE_MANA_RUBY = { name = "Conjure Mana Ruby", ziel = {  }, gruppe = { "This ruby has held more mana than some librarians have read about.", "*seals deep crimson streams of mana inside a glittering ruby.*", "Within the ruby, stored power awaits its moment.", "*gathers scattered sparks into something solid enough to touch.*" } },
    POLYMORPH_COW = { name = "Polymorph: Cow", ziel = { "%s, I hope you have nothing against cowbells.", "Four legs and plenty of grass for you today.", "*traces a cow's outline in softly glowing runes.*", "%s, I trust you know your way around a pasture." }, gruppe = { "A woollier appearance might suit you.", "*sketches the outline of a sheep.*", "Four legs and plenty of grass for you today.", "*traces a cow's outline in softly glowing runes.*", "Transformation is a precise art; the fleece is incidental.", "*checks the spell's outline for any unexpected horns.*", "A temporary change of shape can be wonderfully persuasive.", "Some transformations call for a particularly generous pasture.", "*turns a rune and watches the outlines shift.*" } },
    COMPREHEND_SCROLL = { name = "Comprehend Scroll", ziel = {  }, gruppe = { "Some scrolls yield their meaning only to patient eyes.", "*holds a scroll to the light and unravels its sealed markings.*", "The script is old, but its logic has not aged.", "*nudges a floating glyph by a hair's breadth and listens to its hum.*" } },
    STUDY = { name = "Study", ziel = {  }, gruppe = { "Those who only cast and never read remain apprentices.", "*smooths a note written in the margin of an ancient tome.*", "The most dangerous rune is the one you only half understand.", "*nudges a floating glyph by a hair's breadth and listens to its hum.*" } },
    TELEPORT_STORMWIND = { name = "Teleport: STORMWIND", ziel = {  }, gruppe = { "Stormwind is only one well-placed rune away.", "*folds the image of white towers into a spinning point of light.*", "Stormwind is one clear thought away from here.", "*rotates the coordinates of a floating map toward the light.*" } },
    PORTAL_STORMWIND = { name = "Portal: STORMWIND", ziel = {  }, gruppe = { "A clear road to Stormwind's gates. One at a time, please.", "*stretches a blue gateway framed by the city's walls.*", "A doorway to Stormwind, preferably without a customs stop in the Nether.", "*rotates the coordinates of a floating map toward the light.*" } },
    TELEPORT_IRONFORGE = { name = "Teleport: IRONFORGE", ziel = {  }, gruppe = { "Ironforge awaits with anvils ringing and warm stone.", "*compresses the outline of a mountain gate into a glowing destination rune.*", "Ironforge's furnaces are easier to locate than its shortcuts.", "*rotates the coordinates of a floating map toward the light.*" } },
    PORTAL_IRONFORGE = { name = "Portal: IRONFORGE", ziel = {  }, gruppe = { "If you smell forge smoke, Ironforge is nearly at hand.", "*opens a gateway where sparks from an anvil flicker for a moment.*", "The gateway to Ironforge almost smells of coal and ore.", "*rotates the coordinates of a floating map toward the light.*" } },
    TELEPORT_DARNASSUS = { name = "Teleport: DARNASSUS", ziel = {  }, gruppe = { "Darnassus calls with quiet gardens and ancient boughs.", "*weaves silver leaf-light into a circle of destination runes.*", "Darnassus waits beyond a veil of leaves and stars.", "*rotates the coordinates of a floating map toward the light.*" } },
    PORTAL_DARNASSUS = { name = "Portal: DARNASSUS", ziel = {  }, gruppe = { "Step softly, please. The trees may be listening on the other side.", "*opens a portal whose rim glimmers like moonlight on leaves.*", "A passage to Darnassus deserves respect for ancient trees.", "*rotates the coordinates of a floating map toward the light.*" } },
    TELEPORT_DALARAN = { name = "Teleport: DALARAN", ziel = {  }, gruppe = { "Dalaran is the finest place to complain about too many incantations.", "*aligns floating spires inside a miniature model of light.*", "Dalaran announces itself in the hum of arcane currents.", "*rotates the coordinates of a floating map toward the light.*" } },
    PORTAL_DALARAN = { name = "Portal: DALARAN", ziel = {  }, gruppe = { "A road to Dalaran. No experiments on the threshold, please.", "*unfolds a circle of violet constellations and floating towers.*", "A portal to Dalaran; please don't correct the runes in transit.", "*rotates the coordinates of a floating map toward the light.*" } },
    TELEPORT_ORGRIMMAR = { name = "Teleport: ORGRIMMAR", ziel = {  }, gruppe = { "Orgrimmar awaits with dust, drums and red walls.", "*sketches an angular gate in red light and disappears into it.*", "Orgrimmar's walls make a sturdy point in any equation.", "*rotates the coordinates of a floating map toward the light.*" } },
    PORTAL_ORGRIMMAR = { name = "Portal: ORGRIMMAR", ziel = {  }, gruppe = { "The way to Orgrimmar is open. Keep your weapons close.", "*opens a wide gate of light edged by the shadows of tall palisades.*", "The way to Orgrimmar is open; mind the height of the threshold.", "*rotates the coordinates of a floating map toward the light.*" } },
    TELEPORT_UNDERCITY = { name = "Teleport: UNDERCITY", ziel = {  }, gruppe = { "Undercity lies deep. I hope the vertical coordinate is correct.", "*lowers a greenish destination rune through layers of shimmering circles.*", "Undercity awaits with cold air and colder greetings.", "*rotates the coordinates of a floating map toward the light.*" } },
    PORTAL_UNDERCITY = { name = "Portal: UNDERCITY", ziel = {  }, gruppe = { "A passage to Undercity. We shall discuss the smell later.", "*opens a shadowy gateway with flickering green edges.*", "This gateway to Undercity requires firm coordinates and firmer nerves.", "*rotates the coordinates of a floating map toward the light.*" } },
    TELEPORT_THUNDER_BLUFF = { name = "Teleport: THUNDER_BLUFF", ziel = {  }, gruppe = { "Thunder Bluff demands a steady hand and respect for the height.", "*sets a windswept cliff platform inside a golden destination circle.*", "Thunder Bluff sits high; my spell saves us the climb.", "*rotates the coordinates of a floating map toward the light.*" } },
    PORTAL_THUNDER_BLUFF = { name = "Portal: THUNDER_BLUFF", ziel = {  }, gruppe = { "The road to Thunder Bluff is open. Watch your first step.", "*stretches a doorway where distant grasses bend in the wind.*", "A doorway to Thunder Bluff, hopefully with solid ground beyond.", "*rotates the coordinates of a floating map toward the light.*" } },
}
